import { DurableObject } from 'cloudflare:workers';
import { Lifecycle } from 'agents/lifecycle';
import { MCPClientManager, MCPConnectionState } from 'agents/mcp/client';

const SERVER_ID = 'tools';

// A plain Durable Object (not an Agent). Our other Workers call listTools() over RPC.
export class ToolGateway extends DurableObject {
  // The manager persists registered servers in this object's SQLite storage and
  // restores them in its onStart hook, so the connection survives eviction.
  mcp = new MCPClientManager('tool-gateway', '1.0.0', { env: this.env });

  lifecycle = Lifecycle.install(this).use(this.mcp);

  #ready;

  async listTools() {
    // Native RPC bypasses fetch, so start the lifecycle (and restore connections) explicitly.
    await this.lifecycle.start();
    this.#ready ??= this.#ensureConnected().finally(() => {
      this.#ready = undefined;
    });
    await this.#ready;
    return this.mcp.listTools();
  }

  async #ensureConnected() {
    const url = new URL(this.env.TOOLS_MCP_URL).href;
    const stored = this.mcp.listServers().find((s) => s.id === SERVER_ID);

    if (stored && new URL(stored.server_url).href !== url) {
      await this.mcp.removeServer(SERVER_ID);
    } else if (stored) {
      // Restored from storage on start; wait for reconnect + discovery to settle.
      await this.mcp.waitForConnections({ timeout: 30_000 });
      const state = this.mcp.mcpConnections[SERVER_ID]?.connectionState;
      if (state === MCPConnectionState.READY) return;
    }

    if (!this.mcp.listServers().some((s) => s.id === SERVER_ID)) {
      await this.mcp.registerServer(SERVER_ID, { url, name: SERVER_ID });
    }
    const result = await this.mcp.connectToServer(SERVER_ID);
    if (result.state !== MCPConnectionState.CONNECTED) {
      throw new Error(`Failed to connect to MCP server at ${url}: ${result.error ?? result.state}`);
    }
    const discovered = await this.mcp.discoverIfConnected(SERVER_ID);
    if (!discovered?.success) {
      throw new Error(`Failed to discover MCP server tools: ${discovered?.error ?? 'connection not found'}`);
    }
  }
}

